#!/bin/sh
# One deployment transaction: snapshot -> backup -> migrate/start -> smoke -> commit.
# Jenkins also calls rollback from post.unsuccessful after an interrupted shell.
set -eu
. scripts/compose.sh
umask 077
state="${RELEASE_STATE_DIR:-.releases}"
mkdir -p "$state"

rollback() {
    [ -f "$state/pending" ] || return 0
    if [ -s "$state/previous.env" ]; then
        # Generated by this script from Docker image IDs and image version labels.
        . "$state/previous.env"
        export BACKEND_IMAGE FRONTEND_IMAGE
        echo "Restoring the previous backend and frontend images"
        # Do not rerun or downgrade migrations during an application rollback.
        # Explicit returns are essential: this function is also called in an OR-list
        # from the EXIT trap, where POSIX shells disable implicit `set -e` handling.
        compose up -d --no-build --no-deps --wait --wait-timeout 180 backend frontend || return 1
        smoke "$PREVIOUS_BUILD" || return 1
        printf 'BACKEND_IMAGE=%s\nFRONTEND_IMAGE=%s\nBUILD=%s\nREVISION=%s\n' \
            "$BACKEND_IMAGE" "$FRONTEND_IMAGE" "$PREVIOUS_BUILD" "${PREVIOUS_REVISION:-unknown}" > "$state/current.env" || return 1
    else
        echo "First release failed; stopping application containers and preserving the database"
        compose stop backend frontend || return 1
    fi
    rm -f "$state/pending"
}

case "${1:-deploy}" in
    rollback) rollback; exit 0 ;;
    deploy) ;;
    *) echo "Usage: sh scripts/deploy.sh [deploy|rollback]" >&2; exit 2 ;;
esac

[ ! -e "$state/pending" ] || { echo "An interrupted deployment needs rollback first" >&2; exit 1; }
: "${IMAGE_TAG:?Set IMAGE_TAG to the tested build identity}"
: "${BACKEND_IMAGE:?Set BACKEND_IMAGE to a tested image digest or local image ID}"
: "${FRONTEND_IMAGE:?Set FRONTEND_IMAGE to a tested image digest or local image ID}"
for image in "$BACKEND_IMAGE" "$FRONTEND_IMAGE"; do
    case "$image" in sha256:*|*@sha256:*) ;; *) echo "Deployment requires immutable image references" >&2; exit 1;; esac
    docker image inspect "$image" > /dev/null
    build=$(docker image inspect --format '{{index .Config.Labels "org.opencontainers.image.version"}}' "$image")
    [ "$build" = "$IMAGE_TAG" ] || { echo "Image build label does not match IMAGE_TAG" >&2; exit 1; }
done
compose config --quiet
if [ "${SPROUT_PRODUCTION:-0}" = 1 ]; then
    sh scripts/prepare-db-secret.sh
fi

# Save actual image IDs (never infer the frontend or previous namespace from a tag).
previous_backend=$(compose ps -aq backend)
previous_frontend=$(compose ps -aq frontend)
: > "$state/previous.env"
if [ -n "$previous_backend" ] && [ -n "$previous_frontend" ]; then
    backend_id=$(docker inspect --format '{{.Image}}' "$previous_backend")
    frontend_id=$(docker inspect --format '{{.Image}}' "$previous_frontend")
    for previous_image in "$backend_id" "$frontend_id"; do
        docker image inspect "$previous_image" > /dev/null 2>&1 || {
            echo "Previous release image is unavailable; restore it before deploying. Keep release tags unique and retain rollback images." >&2
            exit 1
        }
    done
    previous_build=$(docker image inspect --format '{{index .Config.Labels "org.opencontainers.image.version"}}' "$backend_id")
    previous_revision=$(docker image inspect --format '{{index .Config.Labels "org.opencontainers.image.revision"}}' "$backend_id")
    case "$previous_revision" in ''|*[!a-zA-Z0-9_.-]*) previous_revision=unknown;; esac
    case "$previous_build" in ''|*[!a-zA-Z0-9_.-]*) echo "Previous release lacks a valid build label; migrate it manually before automatic deployment" >&2; exit 1;; esac
    printf 'BACKEND_IMAGE=%s\nFRONTEND_IMAGE=%s\nPREVIOUS_BUILD=%s\nPREVIOUS_REVISION=%s\n' \
        "$backend_id" "$frontend_id" "$previous_build" "$previous_revision" > "$state/previous.env"
fi

# Take the backup while the old database is running, before migrations modify it.
compose up -d --no-build --wait --wait-timeout 180 db
backup="${BACKUP_DIR:-.backups}/$(date -u +%Y%m%dT%H%M%SZ)-$IMAGE_TAG.dump"
sh scripts/backup-db.sh "$backup"

touch "$state/pending"
trap 'rc=$?; trap - EXIT; if [ "$rc" -ne 0 ]; then rollback || echo "ROLLBACK FAILED: operator recovery required" >&2; fi; exit "$rc"' EXIT
trap 'exit 130' INT
trap 'exit 143' TERM HUP
compose up -d --no-build --wait --wait-timeout 180 db migrate backend frontend
smoke "$IMAGE_TAG"
printf 'BACKEND_IMAGE=%s\nFRONTEND_IMAGE=%s\nBUILD=%s\nREVISION=%s\n' \
    "$BACKEND_IMAGE" "$FRONTEND_IMAGE" "$IMAGE_TAG" "${APP_REVISION:-unknown}" > "$state/current.env"
rm -f "$state/pending"
echo "Release $IMAGE_TAG verified and recorded in $state/current.env"
